class QuotationResource extends Resource { protected static ?string $model=Quotation::class; protected static ?string $navigationGroup='Finance'; protected static ?string $navigationIcon='heroicon-o-document-text'; public static function canViewAny():bool{return auth()->user()?->can('financials.manage')??false;} public static function form(Form $form):Form{return $form->schema([Forms\Components\Select::make('service_request_id')->relationship('request','reference')->required(),Forms\Components\Repeater::make('items')->relationship()->schema([Forms\Components\TextInput::make('description')->required(),Forms\Components\TextInput::make('quantity')->numeric()->minValue(1)->default(1)->required(),Forms\Components\TextInput::make('unit_price')->numeric()->minValue(0)->required(),Forms\Components\TextInput::make('discount')->numeric()->minValue(0)->default(0)])->columns(4)->minItems(1),Forms\Components\TextInput::make('discount')->numeric()->minValue(0)->default(0),Forms\Components\TextInput::make('tax')->numeric()->minValue(0)->default(0),Forms\Components\DatePicker::make('issued_at'),Forms\Components\DatePicker::make('valid_until'),Forms\Components\Select::make('status')->options(['draft'=>'Draft','sent'=>'Sent','accepted'=>'Accepted','rejected'=>'Rejected','expired'=>'Expired','cancelled'=>'Cancelled'])->default('draft'),Forms\Components\Textarea::make('customer_notes'),Forms\Components\Textarea::make('internal_notes')]);} public static function table(Table $table):Table{return $table->defaultSort('created_at','desc')->columns([Tables\Columns\TextColumn::make('number')->searchable(),Tables\Columns\TextColumn::make('request.reference')->searchable(),Tables\Columns\TextColumn::make('total')->money('AED'),Tables\Columns\BadgeColumn::make('status')->searchable(),Tables\Columns\TextColumn::make('valid_until')->date()->sortable()])->filters([Tables\Filters\SelectFilter::make('status')->options(['draft'=>'Draft','sent'=>'Sent','accepted'=>'Accepted','rejected'=>'Rejected','expired'=>'Expired','cancelled'=>'Cancelled']),Tables\Filters\Filter::make('created_at')->form([Forms\Components\DatePicker::make('from'),Forms\Components\DatePicker::make('until')])])->actions([Tables\Actions\EditAction::make(),Tables\Actions\Action::make('send')->label('Mark sent')->requiresConfirmation()->action(fn(Quotation $r)=>$r->update(['status'=>'sent']))]);} public static function getPages():array{return ['index'=>Pages\ListQuotations::route('/'),'create'=>Pages\CreateQuotation::route('/create'),'view'=>Pages\ViewQuotation::route('/{record}'),'edit'=>Pages\EditQuotation::route('/{record}/edit')];} }
